mapper.select:
SELECT 
FROM ai_run_lease
WHERE workspace_id = #{workspaceId}
  AND subject_kind = #{subjectKind}
  AND subject_id = #{subjectId}
FOR UPDATE

mapper.update:
UPDATE ai_run_lease
SET owner = #{owner},
    epoch = epoch + 1,
    acquired_at = CURRENT_TIMESTAMP(6),
    heartbeat_at = CURRENT_TIMESTAMP(6),
    expires_at = DATE_ADD(CURRENT_TIMESTAMP(6), INTERVAL #{ttlSeconds} SECOND),
    released_at = NULL
WHERE workspace_id = #{workspaceId}
  AND subject_kind = #{subjectKind}
  AND subject_id = #{subjectId}
  AND owner IS NOT NULL
  AND epoch = #{expectedEpoch}
  AND expires_at < CURRENT_TIMESTAMP(6)

UPDATE ai_run_lease
SET heartbeat_at = CURRENT_TIMESTAMP(6),
    expires_at = DATE_ADD(CURRENT_TIMESTAMP(6), INTERVAL #{ttlSeconds} SECOND)
WHERE workspace_id = #{workspaceId}
  AND subject_kind = #{subjectKind}
  AND subject_id = #{subjectId}
  AND owner = #{owner}
  AND epoch = #{epoch}

UPDATE ai_run_lease
SET owner = NULL,
    released_at = CURRENT_TIMESTAMP(6),
    expires_at = GREATEST(CURRENT_TIMESTAMP(6), acquired_at)
WHERE workspace_id = #{workspaceId}
  AND subject_kind = #{subjectKind}
  AND subject_id = #{subjectId}
  AND owner = #{owner}
  AND epoch = #{epoch}

mapper.delete:
DELETE FROM ai_run_lease
WHERE workspace_id = #{workspaceId}
  AND subject_kind IN

          #{subjectKind}

  AND owner IS NULL
  AND released_at <
      DATE_SUB(CURRENT_TIMESTAMP(6), INTERVAL #{retentionSeconds} SECOND)
ORDER BY released_at
LIMIT #{limit}
